python3 - << 'PY'
import pandas as pd
import numpy as np
import re

train = pd.read_csv('b3_supercon_train.csv')
pool = pd.read_csv('b3_supercon_pool.csv')

def parse_comp(s):
    tokens = re.findall(r'([A-Z][a-z]?)(\d*\.?\d*)', s)
    d = {}
    for el, num in tokens:
        n = float(num) if num else 1.0
        d[el] = d.get(el, 0.0) + n
    return d

train['p'] = train['composition'].apply(parse_comp)
pool['p'] = pool['composition'].apply(parse_comp)

print("===== Hg cuprates in train =====")
for _,r in train.iterrows():
    d=r['p']
    if 'Hg' in d and 'Cu' in d:
        print(f"Tc={r['target']:7.2f}  Ca={d.get('Ca',0):.2f} Ba={d.get('Ba',0):.2f} Sr={d.get('Sr',0):.2f} Cu={d.get('Cu',0):.2f} Hg={d.get('Hg',0):.2f}  {r['composition']}")

print("\n===== Tl cuprates in train =====")
for _,r in train.iterrows():
    d=r['p']
    if 'Tl' in d and 'Cu' in d:
        print(f"Tc={r['target']:7.2f}  Ca={d.get('Ca',0):.2f} Ba={d.get('Ba',0):.2f} Sr={d.get('Sr',0):.2f} Cu={d.get('Cu',0):.2f} Tl={d.get('Tl',0):.2f}  {r['composition']}")

print("\n===== Bi cuprates Tc>=80 in train =====")
for _,r in train.sort_values('target', ascending=False).iterrows():
    d=r['p']
    if 'Bi' in d and 'Cu' in d and r['target']>=70:
        print(f"Tc={r['target']:7.2f}  Ca={d.get('Ca',0):.2f} Sr={d.get('Sr',0):.2f} Cu={d.get('Cu',0):.2f} Bi={d.get('Bi',0):.2f} Pb={d.get('Pb',0):.2f}  {r['composition']}")

print("\n===== High Tc non Bi/Tl/Hg =====")
for _,r in train.sort_values('target', ascending=False).iterrows():
    d=r['p']
    if r['target']>=80 and not any(x in d for x in ['Bi','Tl','Hg']):
        print(f"Tc={r['target']:7.2f}  {r['composition']}")

print("\n===== Ba-Ca-Cu-O without RE (Cu-12nn family) =====")
RE = set(['Y','La','Ce','Pr','Nd','Sm','Eu','Gd','Tb','Dy','Ho','Er','Tm','Yb','Lu'])
for _,r in train.iterrows():
    d=r['p']
    if 'Cu' in d and 'O' in d and 'Ba' in d and 'Ca' in d and not (RE & set(d)):
        print(f"Tc={r['target']:7.2f}  {r['composition']}  els={sorted(d)}")

print("\n===== Pool high-n / high family =====")
for _,r in pool.iterrows():
    d=r['p']
    if 'Cu' in d and 'O' in d:
        n_cu = d.get('Cu',0)
        n_ca = d.get('Ca',0)
        # print only promising
        keys = set(d)
        if ('Tl' in d or 'Hg' in d or ('Bi' in d and n_ca>=1.5) or (n_cu>=3.5 and 'Ba' in d and 'Ca' in d and not (RE & keys))):
            print(f"{r['candidate_id']} Cu={n_cu:.2f} Ca={n_ca:.2f} Ba={d.get('Ba',0):.2f} Sr={d.get('Sr',0):.2f}  {r['composition']}")
